-- exasol-mariadb-compat v2026.6.0-14-g773baaa-dirty
-- Auto-generated by build.sh from udfs/ and preprocessor/ — DO NOT EDIT.
-- Install:  exaplus -f dist/mariadb-compat.sql
--     or:   python install.py ...
--
-- Import directly into Exasol via an Exasol connector (exaplus, the
-- pyexasol-based install.py, or any Exasol driver) — NOT through MaxScale.
-- The --/ ... / script-block markers and CREATE SCRIPT bodies below are
-- exaplus/Exasol-native and do not survive a MariaDB client + preprocessor.
--
-- exaplus 25.2.6 does not enter script-body mode for CREATE PREPROCESSOR
-- SCRIPT (works fine for SCALAR SCRIPT). The bundle therefore wraps
-- SCALAR UDFs in --/ ... / blocks and emits PREPROCESSOR scripts with
-- a bare trailing `;` — preprocessor source files must keep `;` out of
-- their Python comments so the bare-`;` form has a single statement
-- terminator at the very end.

CREATE SCHEMA IF NOT EXISTS UTIL
;
CREATE SCHEMA IF NOT EXISTS INFORMATION_SCHEMA
;

-- === views/information_schema/columns.sql ===
-- MariaDB INFORMATION_SCHEMA.COLUMNS over Exasol's SYS.EXA_ALL_COLUMNS.
-- See tables.sql for why this is a view rather than a transpiler rewrite.
--
-- Exasol reports one COLUMN_TYPE string ('VARCHAR(100) UTF8', 'DECIMAL(10,2)'),
-- where MariaDB splits the base name (DATA_TYPE) from the full declaration
-- (COLUMN_TYPE) and the size/precision columns. The base name is the leading
-- run of letters, which also keeps multi-word types intact ('TIMESTAMP WITH
-- LOCAL TIME ZONE', 'DOUBLE PRECISION').
--
-- Exasol has no empty string — '' is NULL — so the columns MariaDB reports as ''
-- (COLUMN_KEY, EXTRA, COLUMN_COMMENT) come back NULL here. A client that tests
-- `EXTRA = ''` rather than checking for a value will not match.
CREATE OR REPLACE VIEW INFORMATION_SCHEMA.COLUMNS AS
SELECT
    'def'                                   AS "TABLE_CATALOG",
    c.COLUMN_SCHEMA                         AS "TABLE_SCHEMA",
    c.COLUMN_TABLE                          AS "TABLE_NAME",
    c.COLUMN_NAME                           AS "COLUMN_NAME",
    c.COLUMN_ORDINAL_POSITION               AS "ORDINAL_POSITION",
    c.COLUMN_DEFAULT                        AS "COLUMN_DEFAULT",
    CASE WHEN c.COLUMN_IS_NULLABLE THEN 'YES' ELSE 'NO' END
                                            AS "IS_NULLABLE",
    LOWER(TRIM(REGEXP_SUBSTR(c.COLUMN_TYPE, '^[A-Za-z][A-Za-z ]*')))
                                            AS "DATA_TYPE",
    CASE WHEN TRIM(REGEXP_SUBSTR(c.COLUMN_TYPE, '^[A-Za-z][A-Za-z ]*')) IN ('VARCHAR', 'CHAR')
         THEN c.COLUMN_MAXSIZE END          AS "CHARACTER_MAXIMUM_LENGTH",
    CASE WHEN TRIM(REGEXP_SUBSTR(c.COLUMN_TYPE, '^[A-Za-z][A-Za-z ]*')) IN ('VARCHAR', 'CHAR')
         THEN CAST(c.COLUMN_MAXSIZE * 4 AS DECIMAL(18, 0)) END
                                            AS "CHARACTER_OCTET_LENGTH",
    CASE WHEN c.COLUMN_NUM_SCALE IS NOT NULL THEN c.COLUMN_NUM_PREC END
                                            AS "NUMERIC_PRECISION",
    c.COLUMN_NUM_SCALE                      AS "NUMERIC_SCALE",
    -- Exasol reports fractional-second precision in COLUMN_NUM_PREC for
    -- TIMESTAMP, where COLUMN_NUM_SCALE is NULL.
    CASE WHEN c.COLUMN_NUM_SCALE IS NULL THEN c.COLUMN_NUM_PREC END
                                            AS "DATETIME_PRECISION",
    CASE WHEN TRIM(REGEXP_SUBSTR(c.COLUMN_TYPE, '^[A-Za-z][A-Za-z ]*')) IN ('VARCHAR', 'CHAR')
         THEN 'utf8mb4' END                 AS "CHARACTER_SET_NAME",
    CASE WHEN TRIM(REGEXP_SUBSTR(c.COLUMN_TYPE, '^[A-Za-z][A-Za-z ]*')) IN ('VARCHAR', 'CHAR')
         THEN 'utf8mb4_general_ci' END      AS "COLLATION_NAME",
    LOWER(REPLACE(c.COLUMN_TYPE, ' UTF8', ''))
                                            AS "COLUMN_TYPE",
    CAST('' AS VARCHAR(3))                  AS "COLUMN_KEY",
    CASE WHEN c.COLUMN_IDENTITY IS NOT NULL THEN 'auto_increment' ELSE '' END
                                            AS "EXTRA",
    'select,insert,update,references'       AS "PRIVILEGES",
    NVL(c.COLUMN_COMMENT, '')               AS "COLUMN_COMMENT",
    'NEVER'                                 AS "IS_GENERATED",
    CAST(NULL AS VARCHAR(2000000))          AS "GENERATION_EXPRESSION"
FROM SYS.EXA_ALL_COLUMNS c
WHERE c.COLUMN_OBJECT_TYPE = 'TABLE'
;

-- === views/information_schema/key_column_usage.sql ===
-- MariaDB INFORMATION_SCHEMA.KEY_COLUMN_USAGE over Exasol's
-- SYS.EXA_ALL_CONSTRAINT_COLUMNS. See tables.sql for why this is a view.
--
-- Exasol names primary-key constraints with a generated identifier
-- (SYS_1327...), where MariaDB always calls them 'PRIMARY'. Clients identify
-- the primary key by that name, so PRIMARY KEY rows are renamed; UNIQUE and
-- FOREIGN KEY constraints keep the name Exasol reports.
--
-- Exasol's REFERENCED_* columns are NULL for non-foreign-key constraints, which
-- matches MariaDB, so the usual `REFERENCED_TABLE_NAME IS NULL` filter for
-- "primary/unique keys only" works unchanged.
CREATE OR REPLACE VIEW INFORMATION_SCHEMA.KEY_COLUMN_USAGE AS
SELECT
    'def'                                   AS "CONSTRAINT_CATALOG",
    cc.CONSTRAINT_SCHEMA                    AS "CONSTRAINT_SCHEMA",
    CASE WHEN cc.CONSTRAINT_TYPE = 'PRIMARY KEY' THEN 'PRIMARY'
         ELSE cc.CONSTRAINT_NAME END        AS "CONSTRAINT_NAME",
    'def'                                   AS "TABLE_CATALOG",
    cc.CONSTRAINT_SCHEMA                    AS "TABLE_SCHEMA",
    cc.CONSTRAINT_TABLE                     AS "TABLE_NAME",
    cc.COLUMN_NAME                          AS "COLUMN_NAME",
    cc.ORDINAL_POSITION                     AS "ORDINAL_POSITION",
    CASE WHEN cc.REFERENCED_TABLE IS NOT NULL THEN cc.ORDINAL_POSITION END
                                            AS "POSITION_IN_UNIQUE_CONSTRAINT",
    cc.REFERENCED_SCHEMA                    AS "REFERENCED_TABLE_SCHEMA",
    cc.REFERENCED_TABLE                     AS "REFERENCED_TABLE_NAME",
    cc.REFERENCED_COLUMN                    AS "REFERENCED_COLUMN_NAME"
FROM SYS.EXA_ALL_CONSTRAINT_COLUMNS cc
-- Exasol also records NOT NULL as a constraint (with a generated name and a NULL
-- ordinal); MariaDB's KEY_COLUMN_USAGE covers key constraints only.
WHERE cc.CONSTRAINT_TYPE IN ('PRIMARY KEY', 'UNIQUE', 'FOREIGN KEY')
;

-- === views/information_schema/processlist.sql ===
-- MariaDB INFORMATION_SCHEMA.PROCESSLIST over Exasol's SYS.EXA_ALL_SESSIONS.
-- See tables.sql for why this is a view. SHOW [FULL] PROCESSLIST is rewritten
-- onto this view by the preprocessor, so both spellings report the same rows.
--
-- These are Exasol sessions, not client connections to MaxScale: the router
-- holds pooled ODBC sessions, and Exasol internals (LogServer) appear too. The
-- data is real, but it answers a slightly different question than it does on
-- MariaDB.
--
-- EXA_ALL_SESSIONS, never EXA_DBA_SESSIONS -- the DBA view exposes far more
-- than a session list should, and this view runs with its owner's rights.
--
-- Exasol reports DURATION as 'H:MM:SS' text where MariaDB reports whole
-- seconds. HOST carries the driver description rather than host:port, INFO the
-- current activity rather than the query text (not available here), and Exasol
-- has no per-session schema, so DB is NULL.
CREATE OR REPLACE VIEW INFORMATION_SCHEMA.PROCESSLIST AS
SELECT
    s.SESSION_ID                            AS "ID",
    s.USER_NAME                             AS "USER",
    s.CLIENT                                AS "HOST",
    CAST(NULL AS VARCHAR(64))               AS "DB",
    s.COMMAND_NAME                          AS "COMMAND",
    CAST(
        TO_NUMBER(REGEXP_SUBSTR(s.DURATION, '[0-9]+', 1, 1)) * 3600
      + TO_NUMBER(REGEXP_SUBSTR(s.DURATION, '[0-9]+', 1, 2)) * 60
      + TO_NUMBER(REGEXP_SUBSTR(s.DURATION, '[0-9]+', 1, 3))
        AS DECIMAL(18, 0))                  AS "TIME",
    s.STATUS                                AS "STATE",
    s.ACTIVITY                              AS "INFO",
    CAST(0 AS DECIMAL(18, 3))               AS "PROGRESS"
FROM SYS.EXA_ALL_SESSIONS s
;

-- === views/information_schema/schemata.sql ===
-- MariaDB INFORMATION_SCHEMA.SCHEMATA over Exasol's SYS.EXA_SCHEMAS.
-- See tables.sql for why this is a view.
--
-- Exasol has no per-schema character set or collation, so those are reported as
-- the utf8mb4 defaults the rest of these views assume.
CREATE OR REPLACE VIEW INFORMATION_SCHEMA.SCHEMATA AS
SELECT
    'def'                                   AS "CATALOG_NAME",
    s.SCHEMA_NAME                           AS "SCHEMA_NAME",
    'utf8mb4'                               AS "DEFAULT_CHARACTER_SET_NAME",
    'utf8mb4_general_ci'                    AS "DEFAULT_COLLATION_NAME",
    CAST(NULL AS VARCHAR(512))              AS "SQL_PATH",
    NVL(s.SCHEMA_COMMENT, '')               AS "SCHEMA_COMMENT"
FROM SYS.EXA_SCHEMAS s
;

-- === views/information_schema/statistics.sql ===
-- MariaDB INFORMATION_SCHEMA.STATISTICS over Exasol's
-- SYS.EXA_ALL_CONSTRAINT_COLUMNS. See tables.sql for why this is a view.
--
-- Clients read STATISTICS to discover a table's indexes and, more importantly,
-- to resolve its primary key — DBeaver's table editor issues
--   SELECT * FROM information_schema.STATISTICS
--   WHERE TABLE_SCHEMA=? AND TABLE_NAME=? ORDER BY TABLE_NAME,INDEX_NAME,SEQ_IN_INDEX
-- on every table open, and without this view that query errors out.
--
-- Source is the constraint catalog, not SYS.EXA_ALL_INDICES. Exasol's indices
-- are auto-created physical join structures (LOCAL/GLOBAL, dropped and rebuilt
-- by the engine, present on staging tables too) and expose their columns only
-- inside a REMARKS string like 'LOCAL INDEX (id)'. Reporting those as MariaDB
-- indexes would name structures the user never created and cannot drop, so
-- only the key constraints Exasol actually enforces are listed.
--
-- Divergences from MariaDB:
--   * PRIMARY KEY and UNIQUE constraints only. InnoDB also auto-creates an
--     index behind every FOREIGN KEY and lists it here; Exasol does not, so
--     those rows are absent.
--   * CARDINALITY is NULL — Exasol keeps no per-index row estimate. A client
--     that sorts or filters on cardinality gets no useful ordering.
--   * Primary keys are renamed to 'PRIMARY', matching TABLE_CONSTRAINTS and
--     KEY_COLUMN_USAGE; the three are routinely joined and must agree.
--   * Exasol has no empty string — '' is NULL — so COMMENT and INDEX_COMMENT
--     come back NULL where MariaDB reports ''. Same caveat as columns.sql.
CREATE OR REPLACE VIEW INFORMATION_SCHEMA.STATISTICS AS
SELECT
    'def'                                   AS "TABLE_CATALOG",
    cc.CONSTRAINT_SCHEMA                    AS "TABLE_SCHEMA",
    cc.CONSTRAINT_TABLE                     AS "TABLE_NAME",
    0                                       AS "NON_UNIQUE",
    cc.CONSTRAINT_SCHEMA                    AS "INDEX_SCHEMA",
    CASE WHEN cc.CONSTRAINT_TYPE = 'PRIMARY KEY' THEN 'PRIMARY'
         ELSE cc.CONSTRAINT_NAME END        AS "INDEX_NAME",
    cc.ORDINAL_POSITION                     AS "SEQ_IN_INDEX",
    cc.COLUMN_NAME                          AS "COLUMN_NAME",
    'A'                                     AS "COLLATION",
    CAST(NULL AS DECIMAL(18, 0))            AS "CARDINALITY",
    -- Exasol has no prefix indexes and no PACK_KEYS equivalent.
    CAST(NULL AS DECIMAL(18, 0))            AS "SUB_PART",
    CAST(NULL AS VARCHAR(10))               AS "PACKED",
    CASE WHEN c.COLUMN_IS_NULLABLE THEN 'YES' ELSE '' END
                                            AS "NULLABLE",
    'BTREE'                                 AS "INDEX_TYPE",
    CAST('' AS VARCHAR(16))                 AS "COMMENT",
    CAST('' AS VARCHAR(1024))               AS "INDEX_COMMENT",
    'NO'                                    AS "IGNORED"
FROM SYS.EXA_ALL_CONSTRAINT_COLUMNS cc
LEFT JOIN SYS.EXA_ALL_COLUMNS c
       ON c.COLUMN_SCHEMA = cc.CONSTRAINT_SCHEMA
      AND c.COLUMN_TABLE  = cc.CONSTRAINT_TABLE
      AND c.COLUMN_NAME   = cc.COLUMN_NAME
WHERE cc.CONSTRAINT_TYPE IN ('PRIMARY KEY', 'UNIQUE')
;

-- === views/information_schema/table_constraints.sql ===
-- MariaDB INFORMATION_SCHEMA.TABLE_CONSTRAINTS over Exasol's
-- SYS.EXA_ALL_CONSTRAINTS. See tables.sql for why this is a view.
--
-- Primary keys are renamed to 'PRIMARY' and NOT NULL constraints are excluded,
-- matching KEY_COLUMN_USAGE — the two are routinely joined on CONSTRAINT_NAME,
-- so they must agree on both.
CREATE OR REPLACE VIEW INFORMATION_SCHEMA.TABLE_CONSTRAINTS AS
SELECT
    'def'                                   AS "CONSTRAINT_CATALOG",
    ct.CONSTRAINT_SCHEMA                    AS "CONSTRAINT_SCHEMA",
    CASE WHEN ct.CONSTRAINT_TYPE = 'PRIMARY KEY' THEN 'PRIMARY'
         ELSE ct.CONSTRAINT_NAME END        AS "CONSTRAINT_NAME",
    ct.CONSTRAINT_SCHEMA                    AS "TABLE_SCHEMA",
    ct.CONSTRAINT_TABLE                     AS "TABLE_NAME",
    ct.CONSTRAINT_TYPE                      AS "CONSTRAINT_TYPE"
FROM SYS.EXA_ALL_CONSTRAINTS ct
WHERE ct.CONSTRAINT_TYPE IN ('PRIMARY KEY', 'UNIQUE', 'FOREIGN KEY')
;

-- === views/information_schema/tables.sql ===
-- MariaDB INFORMATION_SCHEMA.TABLES over Exasol's SYS.EXA_ALL_TABLES.
--
-- Clients query information_schema with arbitrary column lists, predicates and
-- joins, so this is a real view rather than a transpiler rewrite: any shape of
-- SQL works against it, and the MariaDB -> Exasol name mapping lives in one place.
-- The unquoted reference `information_schema.TABLES` reaches this view because
-- Exasol is installed with SQL_IDENTIFIER_COMPARISON = 'IGNORE CASE'.
--
-- Columns are listed in MariaDB's order so that clients selecting * and indexing
-- positionally see what they expect. Exasol has no equivalent for the storage-engine
-- columns; they are constant or NULL.
CREATE OR REPLACE VIEW INFORMATION_SCHEMA.TABLES AS
SELECT
    'def'                                   AS "TABLE_CATALOG",
    t.TABLE_SCHEMA                          AS "TABLE_SCHEMA",
    t.TABLE_NAME                            AS "TABLE_NAME",
    'BASE TABLE'                            AS "TABLE_TYPE",
    'EXASOL'                                AS "ENGINE",
    CAST(10 AS DECIMAL(18, 0))              AS "VERSION",
    CAST(NULL AS VARCHAR(10))               AS "ROW_FORMAT",
    t.TABLE_ROW_COUNT                       AS "TABLE_ROWS",
    CAST(NULL AS DECIMAL(18, 0))            AS "AVG_ROW_LENGTH",
    CAST(NULL AS DECIMAL(18, 0))            AS "DATA_LENGTH",
    CAST(NULL AS DECIMAL(18, 0))            AS "MAX_DATA_LENGTH",
    CAST(NULL AS DECIMAL(18, 0))            AS "INDEX_LENGTH",
    CAST(NULL AS DECIMAL(18, 0))            AS "DATA_FREE",
    CAST(NULL AS DECIMAL(18, 0))            AS "AUTO_INCREMENT",
    CAST(NULL AS TIMESTAMP)                 AS "CREATE_TIME",
    CAST(NULL AS TIMESTAMP)                 AS "UPDATE_TIME",
    CAST(NULL AS TIMESTAMP)                 AS "CHECK_TIME",
    'utf8mb4_general_ci'                    AS "TABLE_COLLATION",
    CAST(NULL AS DECIMAL(18, 0))            AS "CHECKSUM",
    CAST('' AS VARCHAR(255))                AS "CREATE_OPTIONS",
    NVL(t.TABLE_COMMENT, '')                AS "TABLE_COMMENT"
FROM SYS.EXA_ALL_TABLES t
;

-- === views/util/show_create_table.sql ===
-- Reconstructs a MariaDB-shaped CREATE TABLE statement per table, for the
-- preprocessor to serve SHOW CREATE TABLE from. Exasol stores no DDL text --
-- there is nothing to fetch -- so this is assembled from the catalog with
-- GROUP_CONCAT, one row per table.
--
-- It therefore describes the table Exasol HAS, not the statement that created
-- it. For CDC-replicated tables the MariaDB original never existed here, so
-- expect Exasol's types (DECIMAL(18,0) where MariaDB said int), no secondary
-- indexes or KEY lines (Exasol has none), and no foreign keys unless Exasol
-- itself holds the constraint. A primary key Exasol holds as disabled -- which
-- is how CDC creates them, and why such a key can sit on a nullable column --
-- is emitted with DISABLE, so running the DDL reproduces the table exactly
-- rather than silently adding NOT NULL.
--
-- The DDL is Exasol SQL -- double-quoted identifiers in the case Exasol stores
-- them, Exasol type names, no ENGINE or CHARSET clause -- so it can be run to
-- recreate the table. Emitting MariaDB syntax around Exasol types would produce
-- a statement valid in neither database.
--
-- Lives in UTIL rather than INFORMATION_SCHEMA because MariaDB has no such
-- table -- SHOW CREATE TABLE is the only interface to it.
CREATE OR REPLACE VIEW UTIL.SHOW_CREATE_TABLE AS
WITH cols AS (
    SELECT
        c.COLUMN_SCHEMA AS TABLE_SCHEMA,
        c.COLUMN_TABLE  AS TABLE_NAME,
        GROUP_CONCAT(
            '  "' || c.COLUMN_NAME || '" ' || c.COLUMN_TYPE
            || CASE WHEN c.COLUMN_IS_NULLABLE THEN '' ELSE ' NOT NULL' END
            || CASE WHEN c.COLUMN_DEFAULT IS NULL THEN ''
                    ELSE ' DEFAULT ' || TRIM(c.COLUMN_DEFAULT) END
            || CASE WHEN c.COLUMN_IDENTITY IS NULL THEN '' ELSE ' IDENTITY' END
            ORDER BY c.COLUMN_ORDINAL_POSITION
            SEPARATOR ',' || CHR(10)) AS COLUMN_LIST
    FROM SYS.EXA_ALL_COLUMNS c
    WHERE c.COLUMN_OBJECT_TYPE = 'TABLE'
    GROUP BY c.COLUMN_SCHEMA, c.COLUMN_TABLE
),
pk AS (
    SELECT
        cc.CONSTRAINT_SCHEMA AS TABLE_SCHEMA,
        cc.CONSTRAINT_TABLE  AS TABLE_NAME,
        GROUP_CONCAT('"' || cc.COLUMN_NAME || '"'
                     ORDER BY cc.ORDINAL_POSITION
                     SEPARATOR ', ') AS KEY_LIST,
        MIN(ct.CONSTRAINT_ENABLED) AS KEY_ENABLED
    FROM SYS.EXA_ALL_CONSTRAINT_COLUMNS cc
    JOIN SYS.EXA_ALL_CONSTRAINTS ct
      ON ct.CONSTRAINT_SCHEMA = cc.CONSTRAINT_SCHEMA
     AND ct.CONSTRAINT_TABLE = cc.CONSTRAINT_TABLE
     AND ct.CONSTRAINT_NAME = cc.CONSTRAINT_NAME
    WHERE cc.CONSTRAINT_TYPE = 'PRIMARY KEY'
    GROUP BY cc.CONSTRAINT_SCHEMA, cc.CONSTRAINT_TABLE
)
SELECT
    t.TABLE_SCHEMA                          AS "TABLE_SCHEMA",
    t.TABLE_NAME                            AS "TABLE_NAME",
    'CREATE TABLE "' || t.TABLE_NAME || '" (' || CHR(10)
        || cols.COLUMN_LIST
        || CASE WHEN pk.KEY_LIST IS NULL THEN ''
                ELSE ',' || CHR(10) || '  PRIMARY KEY (' || pk.KEY_LIST || ')'
                     || CASE WHEN pk.KEY_ENABLED THEN '' ELSE ' DISABLE' END END
        || CHR(10) || ')'
                                            AS "DDL"
FROM SYS.EXA_ALL_TABLES t
JOIN cols
  ON cols.TABLE_SCHEMA = t.TABLE_SCHEMA AND cols.TABLE_NAME = t.TABLE_NAME
LEFT JOIN pk
  ON pk.TABLE_SCHEMA = t.TABLE_SCHEMA AND pk.TABLE_NAME = t.TABLE_NAME
;

-- === udfs/json/json_extract.sql ===
--/
CREATE OR REPLACE LUA SCALAR SCRIPT UTIL.JSON_EXTRACT(
    doc   VARCHAR(2000000),
    paths VARCHAR(2000000)
) RETURNS VARCHAR(2000000) AS

-- MariaDB JSON_EXTRACT semantics:
--   - one path  -> that match as JSON text (strings quoted, numbers bare,
--                  objects/arrays preserved)
--   - multi     -> JSON array of found values, missing paths silently skipped
--   - all miss  -> NULL
-- Path grammar: "$", "$.key", "$[idx]", combinations. Wildcards are not supported
-- and behave as "missing". NB MariaDB does NOT error on them as an earlier version
-- of this comment claimed -- it implements them, so JSON_EXTRACT('{"a":1}', '$.*')
-- is [1] on MariaDB 11.8 and NULL here. Returning NULL keeps that a visible
-- absence rather than a wrong answer; implementing $.* / $[*] / $** is the
-- outstanding gap in this UDF.
--
-- `paths` is always a JSON array of path strings, packed by the preprocessor's
-- JSONExtract branch (json.dumps of the path list) -- even a single path arrives
-- as ["$.a"]. A bare JSON string is also accepted.
--
-- WHY THIS SCANS TEXT INSTEAD OF DECODING: MariaDB re-serializes the matched value with
-- normalized separators (", " and ": ") but keeps every scalar's ORIGINAL text
-- and the document's key ORDER. Verified against MariaDB 11.8:
--     JSON_EXTRACT('{"b":2,"a":1}', '$')            -> {"b": 2, "a": 1}  (not sorted)
--     JSON_EXTRACT('{"a":1e2}', '$.a')              -> 1e2               (not 100.0)
--     JSON_EXTRACT('{"a":123456789012345678901}', '$.a')
--                                                   -> 123456789012345678901
--     JSON_EXTRACT('{"a":"café"}', '$.a')           -> "café"           (raw UTF-8)
-- A decode/re-encode round trip cannot do this in Lua: cjson has no key order,
-- turns every number into a double (so the 21-digit integer above is corrupted
-- and 1e2 becomes 100), and escapes '/' as '\/'. So this scans the source text
-- and re-emits the matched span verbatim except for separator whitespace.
--
-- PERFORMANCE SHAPE (why the code is written the way it is): a JSON parser written
-- in C does its work at C speed, so a naive interpreted Lua scanner LOSES on bulk
-- throughput -- measured 0.5x per row on nested paths in the first draft of this
-- UDF -- while still winning ~9x on per-statement latency, because a LUA script
-- skips the PYTHON3 UDF container startup (+5 ms vs +72 ms). Two structural choices
-- claw the throughput back:
--   1. VALIDATION IS DELEGATED TO C. cjson.decode parses the document purely to
--      confirm it is well-formed and the result is discarded. Validating in
--      interpreted Lua was the single largest cost in the first draft. cjson's
--      acceptance is slightly loose, notably allowing NaN/Infinity.
--   2. NAVIGATION NEVER READS BYTE BY BYTE. Because validation already proved the
--      document well-formed, skipping a value only has to find its extent, not
--      re-verify it: string.find jumps to the next structural character in C, and
--      a skipped object/array is consumed by bracket-depth counting rather than by
--      recursive descent. Single-character reads use string.byte, never
--      string.sub, which allocates a one-character string per read.
-- Key comparison likewise avoids allocating: the candidate key's length is checked
-- against the target first, then string.find(plain) confirms it in place, so no
-- substring is materialized for keys that do not match.
--
-- Known limitations, all confined to loosely-formed inputs or to what the path
-- grammar cannot express:
--   - object keys are matched by their raw text, so a path cannot reach a key
--     written with escapes ({"a": 1} is not found by $.a). The path grammar
--     only admits [A-Za-z_][A-Za-z_0-9]* keys, so such keys are unreachable anyway.
--   - JSON's no-leading-zero rule is not enforced: cjson accepts '01', so such a
--     document extracts here instead of yielding NULL.
--   - cjson's default nesting limit (1000) applies to validation, so a document
--     nested deeper than that yields NULL.

local cjson = require('cjson')
local byte, find, sub, match = string.byte, string.find, string.sub, string.match

local QUOTE, LBRACE, LBRACKET, RBRACE, RBRACKET = 34, 123, 91, 125, 93
local COLON, COMMA, DOLLAR, LOWER_U = 58, 44, 36, 117
local SPACE, TAB, LF, CR = 32, 9, 10, 13

local function skip_ws(s, i)
    local c = byte(s, i)
    while c == SPACE or c == TAB or c == LF or c == CR do
        i = i + 1
        c = byte(s, i)
    end
    return i
end

-- Index just past the closing quote of the string starting at i. Jumps quote to
-- quote in C; only a backslash forces a per-escape step.
local function scan_string(s, i)
    local j = i + 1
    while true do
        local k = find(s, '["\\]', j)
        if not k then
            return nil
        end
        if byte(s, k) == QUOTE then
            return k + 1
        end
        j = (byte(s, k + 1) == LOWER_U) and k + 6 or k + 2
    end
end

-- Index just past the value starting at i (which must be non-whitespace). Assumes
-- the document already validated, so this only measures extent.
local function skip_value(s, i)
    local c = byte(s, i)
    if c == QUOTE then
        return scan_string(s, i)
    end
    if c == LBRACE or c == LBRACKET then
        local depth = 0
        local j = i
        while true do
            local k = find(s, '[%[%]{}"]', j)
            if not k then
                return nil
            end
            local ch = byte(s, k)
            if ch == QUOTE then
                j = scan_string(s, k)
                if not j then
                    return nil
                end
            else
                if ch == LBRACE or ch == LBRACKET then
                    depth = depth + 1
                else
                    depth = depth - 1
                    if depth == 0 then
                        return k + 1
                    end
                end
                j = k + 1
            end
        end
    end
    -- Scalar: numbers and true/false/null contain no structural character, so the
    -- value ends at the next one (or at end of document for a bare scalar).
    local k = find(s, '[,%]}]', i)
    local e = (k or #s + 1) - 1
    local b = byte(s, e)
    while b == SPACE or b == TAB or b == LF or b == CR do
        e = e - 1
        b = byte(s, e)
    end
    return e + 1
end

-- Value start for `key` inside the object at i, or nil when absent.
local function find_key(s, i, key)
    local keylen = #key
    local j = skip_ws(s, i + 1)
    if byte(s, j) == RBRACE then
        return nil
    end
    while true do
        local kend = scan_string(s, j)
        if not kend then
            return nil
        end
        -- length first, then an in-place compare: no substring is allocated
        local hit = (kend - j - 2 == keylen) and find(s, key, j + 1, true) == j + 1
        local v = skip_ws(s, skip_ws(s, kend) + 1)
        if hit then
            return v
        end
        local e = skip_value(s, v)
        if not e then
            return nil
        end
        j = skip_ws(s, e)
        if byte(s, j) ~= COMMA then
            return nil
        end
        j = skip_ws(s, j + 1)
    end
end

-- Value start for 0-based `want` inside the array at i, or nil when out of range.
local function find_index(s, i, want)
    local j = skip_ws(s, i + 1)
    if byte(s, j) == RBRACKET then
        return nil
    end
    for _ = 1, want do
        local e = skip_value(s, j)
        if not e then
            return nil
        end
        j = skip_ws(s, e)
        if byte(s, j) ~= COMMA then
            return nil
        end
        j = skip_ws(s, j + 1)
    end
    return j
end

-- Re-emit the value at i with MariaDB's separators, every scalar token verbatim.
local function emit(s, i, out)
    local c = byte(s, i)
    if c ~= LBRACE and c ~= LBRACKET then
        local e = skip_value(s, i)
        out[#out + 1] = sub(s, i, e - 1)
        return e
    end
    local is_obj = (c == LBRACE)
    local close = is_obj and RBRACE or RBRACKET
    out[#out + 1] = is_obj and '{' or '['
    local j = skip_ws(s, i + 1)
    if byte(s, j) ~= close then
        local first = true
        while true do
            if first then
                first = false
            else
                out[#out + 1] = ', '
            end
            if is_obj then
                local kend = scan_string(s, j)
                out[#out + 1] = sub(s, j, kend - 1)
                out[#out + 1] = ': '
                j = skip_ws(s, skip_ws(s, kend) + 1)
            end
            j = skip_ws(s, emit(s, j, out))
            if byte(s, j) == close then
                break
            end
            j = skip_ws(s, j + 1)
        end
    end
    out[#out + 1] = is_obj and '}' or ']'
    return j + 1
end

-- Start index of the value `path` selects, or nil when unsupported or missing.
local function locate(s, path)
    if type(path) ~= 'string' or byte(path, 1) ~= DOLLAR then
        return nil
    end
    local rest = sub(path, 2)
    if find(rest, '%*') or find(rest, '?', 1, true) or find(rest, '(', 1, true) then
        return nil
    end
    local at = skip_ws(s, 1)
    local pos = 1
    local len = #rest
    while pos <= len do
        local key, nxt = match(rest, '^%.([%a_][%w_]*)()', pos)
        if key then
            if byte(s, at) ~= LBRACE then
                return nil
            end
            at = find_key(s, at, key)
            pos = nxt
        else
            local idx
            idx, nxt = match(rest, '^%[(%d+)%]()', pos)
            if not idx then
                return nil
            end
            local want = tonumber(idx)
            if byte(s, at) ~= LBRACKET then
                -- MariaDB treats any non-array value as a one-element array, so
                -- $[0] resolves to the value itself and every higher index
                -- misses (verified on 11.8: JSON_EXTRACT('{"a":1}', '$[0]') is
                -- {"a": 1}, '$[1]' is NULL, and '5' with '$[0]' is 5). Staying at
                -- the same position composes correctly, so $[0].a and $[0][0] work.
                if want ~= 0 then
                    return nil
                end
            else
                at = find_index(s, at, want)
            end
            pos = nxt
        end
        if not at then
            return nil
        end
    end
    return at
end

function run(ctx)
    if ctx.doc == null or ctx.paths == null then
        return null
    end
    local doc = ctx.doc
    -- Validate in C and discard the result; everything below assumes well-formed
    -- input, which is what makes the interpreted navigation cheap.
    if not pcall(cjson.decode, doc) then
        return null
    end

    local ok, path_list = pcall(cjson.decode, ctx.paths)
    if not ok then
        return null
    end
    if type(path_list) ~= 'table' then
        path_list = {path_list}
    end

    local found = {}
    for _, p in ipairs(path_list) do
        local at = locate(doc, p)
        if at then
            local out = {}
            emit(doc, at, out)
            found[#found + 1] = table.concat(out)
        end
    end

    if #found == 0 then
        return null
    end
    if #path_list == 1 then
        return found[1]
    end
    return '[' .. table.concat(found, ', ') .. ']'
end
/

-- === udfs/json/json_merge_preserve.sql ===
--/
CREATE OR REPLACE LUA SCALAR SCRIPT UTIL.JSON_MERGE_PRESERVE(...)
RETURNS VARCHAR(2000000) AS

-- MariaDB JSON_MERGE_PRESERVE semantics:
--   - Requires >= 2 args.
--   - Any NULL arg -> NULL.
--   - Adjacent objects: union by key; if a key collides, values are combined
--     (recursively merged: two objects -> nested merge; everything else -> autowrap
--     each side to an array and concatenate).
--   - Adjacent arrays: concatenate.
--   - Mixed object/array or scalars: autowrap each side to an array and concatenate.
-- JSON_MERGE is a deprecated MariaDB alias and shares the same semantics; the
-- preprocessor maps both names to this UDF.
-- Invalid JSON in any arg -> NULL (MariaDB raises; we return NULL conservatively
-- rather than aborting the whole statement).
--
-- COMPOSES TEXT, NEVER DECODES (same reasoning as udfs/json/json_extract.sql, and it
-- matters more here). MariaDB normalizes separators to ", " and ": " but keeps every
-- scalar's original text, the document's key order, AND duplicate keys. Verified on
-- MariaDB 11.8:
--     ('{"a": 1e2}', '{"b": 2}')      -> {"a": 1e2, "b": 2}
--     ('{"a": 1.50}', '{"b": 2}')     -> {"a": 1.50, "b": 2}
--     ('{"a":1,"a":2}', '{"b":3}')    -> {"a": 1, "a": 2, "b": 3}
-- A decode/re-encode round trip can express none of these: any JSON parser that
-- returns a map collapses duplicate keys to the last one, and cjson normalizes every
-- number through a double. Slicing the source text preserves all three for free: a
-- value that is not involved in a collision is copied out verbatim, and only
-- genuinely colliding values are rebuilt.
--
-- Performance shape (see the longer note in json_extract.sql): validation is handed
-- to cjson.decode so the C parser does the well-formedness work, and everything
-- after that only measures extents -- string.find jumps between structural
-- characters, skipped containers are consumed by bracket-depth counting, and single
-- characters are read with string.byte rather than allocating via string.sub.
--
-- Multi-arg folds left, and each intermediate result is itself normalized JSON text,
-- so the next merge simply treats it as another document. Intermediates are not
-- re-validated: this UDF produced them.
--
-- KNOWN LIMITATION (Lua-only): Exasol rejects DATE and TIMESTAMP inputs to a LUA
-- script declared with a variadic `(...)` signature. See the same block in
-- udfs/string/elt.sql. Academic here --
-- the arguments are JSON documents -- but it is the same boundary.

local cjson = require('cjson')
local byte, find, sub = string.byte, string.find, string.sub

local QUOTE, LBRACE, LBRACKET, RBRACE, RBRACKET = 34, 123, 91, 125, 93
local COMMA, LOWER_U = 44, 117
local SPACE, TAB, LF, CR = 32, 9, 10, 13

local function skip_ws(s, i)
    local c = byte(s, i)
    while c == SPACE or c == TAB or c == LF or c == CR do
        i = i + 1
        c = byte(s, i)
    end
    return i
end

local function scan_string(s, i)
    local j = i + 1
    while true do
        local k = find(s, '["\\]', j)
        if not k then
            return nil
        end
        if byte(s, k) == QUOTE then
            return k + 1
        end
        j = (byte(s, k + 1) == LOWER_U) and k + 6 or k + 2
    end
end

-- Index just past the value starting at i. Assumes validated input, so this only
-- measures extent rather than re-checking the grammar.
local function skip_value(s, i)
    local c = byte(s, i)
    if c == QUOTE then
        return scan_string(s, i)
    end
    if c == LBRACE or c == LBRACKET then
        local depth = 0
        local j = i
        while true do
            local k = find(s, '[%[%]{}"]', j)
            if not k then
                return nil
            end
            local ch = byte(s, k)
            if ch == QUOTE then
                j = scan_string(s, k)
                if not j then
                    return nil
                end
            else
                if ch == LBRACE or ch == LBRACKET then
                    depth = depth + 1
                else
                    depth = depth - 1
                    if depth == 0 then
                        return k + 1
                    end
                end
                j = k + 1
            end
        end
    end
    local k = find(s, '[,%]}]', i)
    local e = (k or #s + 1) - 1
    local b = byte(s, e)
    while b == SPACE or b == TAB or b == LF or b == CR do
        e = e - 1
        b = byte(s, e)
    end
    return e + 1
end



-- Re-emit the value at i with MariaDB's separators, every scalar token verbatim.
local function emit(s, i, out)
    local c = byte(s, i)
    if c ~= LBRACE and c ~= LBRACKET then
        local e = skip_value(s, i)
        out[#out + 1] = sub(s, i, e - 1)
        return e
    end
    local is_obj = (c == LBRACE)
    local close = is_obj and RBRACE or RBRACKET
    out[#out + 1] = is_obj and '{' or '['
    local j = skip_ws(s, i + 1)
    if byte(s, j) ~= close then
        local first = true
        while true do
            if first then
                first = false
            else
                out[#out + 1] = ', '
            end
            if is_obj then
                local kend = scan_string(s, j)
                out[#out + 1] = sub(s, j, kend - 1)
                out[#out + 1] = ': '
                j = skip_ws(s, skip_ws(s, kend) + 1)
            end
            j = skip_ws(s, emit(s, j, out))
            if byte(s, j) == close then
                break
            end
            j = skip_ws(s, j + 1)
        end
    end
    out[#out + 1] = is_obj and '}' or ']'
    return j + 1
end

-- Append the elements of the array at i to an open list, continuing it when
-- `first` is false. Returns the updated `first`.
local function emit_elements(out, s, i, first)
    local j = skip_ws(s, i + 1)
    if byte(s, j) == RBRACKET then
        return first
    end
    while true do
        if first then
            first = false
        else
            out[#out + 1] = ', '
        end
        j = skip_ws(s, emit(s, j, out))
        if byte(s, j) == RBRACKET then
            return first
        end
        j = skip_ws(s, j + 1)
    end
end

-- One side of an autowrap concatenation: an array spreads its elements, anything
-- else contributes itself as a single element.
local function emit_side(out, s, i, first)
    if byte(s, i) == LBRACKET then
        return emit_elements(out, s, i, first)
    end
    if first then
        first = false
    else
        out[#out + 1] = ', '
    end
    emit(s, i, out)
    return first
end

-- Object merges index the right-hand side ONCE into a hash (key -> value start)
-- plus parallel arrays holding its members in document order. The obvious shape --
-- re-scanning the other document to look up each key -- is O(n*m) and re-slices
-- every key twice; on a 7-key merge that alone cost 2x (22.0 -> 11.0 us/row once
-- indexed). The member walks are inlined
-- rather than driven by a callback, so no closure is allocated per merge.
-- First-wins insertion into `bindex` matches MariaDB's handling of a duplicate key
-- within one document: the first occurrence is the one a collision merges against.
-- MariaDB's merge parses the FIRST complete value in each argument and ignores
-- whatever follows, which is NOT how its own JSON_EXTRACT or JSON_VALID behave
-- (both reject trailing content). Verified on 11.8:
--     JSON_MERGE_PRESERVE('{"a":1} x', '{"b":2}')      -> {"a": 1, "b": 2}
--     JSON_MERGE_PRESERVE('{"a":1} {"c":9}', '{"b":2}') -> {"a": 1, "b": 2}
--     JSON_MERGE_PRESERVE('[1] [2]', '[3]')            -> [1, 3]
--     JSON_MERGE_PRESERVE('x {"a":1}', '{"b":2}')      -> NULL  (leading garbage)
--     JSON_MERGE_PRESERVE('{"a":1', '{"b":2}')         -> NULL  (truncated)
-- while JSON_VALID('{"a":1} x') is 0 and JSON_EXTRACT rejects the same input. This
-- runs only after cjson has already refused the whole argument, so the well-formed
-- path pays nothing for it.
local function first_value(s)
    local i = skip_ws(s, 1)
    local c = byte(s, i)
    local e
    if c == LBRACE or c == LBRACKET or c == QUOTE then
        e = skip_value(s, i)
    else
        -- A bare scalar ends at the first delimiter or space: skip_value assumes
        -- well-formed input and would swallow the trailing junk in '1 2'.
        local _, last = find(s, '^[^ \t\n\r,%]}]+', i)
        e = last and last + 1
    end
    if not e then
        return nil
    end
    return sub(s, i, e - 1)
end

local function merge_into(out, sa, ia, sb, ib)
    if byte(sa, ia) ~= LBRACE or byte(sb, ib) ~= LBRACE then
        -- Anything else concatenates as an array: two arrays join, and a non-array
        -- side is autowrapped into one element.
        out[#out + 1] = '['
        local first = emit_side(out, sa, ia, true)
        emit_side(out, sb, ib, first)
        out[#out + 1] = ']'
        return
    end

    local bindex, bkey, bkf, bkt, bvf = {}, {}, {}, {}, {}
    local m = 0
    local j = skip_ws(sb, ib + 1)
    if byte(sb, j) ~= RBRACE then
        while true do
            local kend = scan_string(sb, j)
            if not kend then
                break
            end
            local v = skip_ws(sb, skip_ws(sb, kend) + 1)
            local key = sub(sb, j + 1, kend - 2)
            m = m + 1
            bkey[m], bkf[m], bkt[m], bvf[m] = key, j, kend, v
            if bindex[key] == nil then
                bindex[key] = v
            end
            local e = skip_value(sb, v)
            if not e then
                break
            end
            j = skip_ws(sb, e)
            if byte(sb, j) ~= COMMA then
                break
            end
            j = skip_ws(sb, j + 1)
        end
    end

    out[#out + 1] = '{'
    local first = true
    local seen = {}
    j = skip_ws(sa, ia + 1)
    if byte(sa, j) ~= RBRACE then
        while true do
            local kend = scan_string(sa, j)
            if not kend then
                break
            end
            local v = skip_ws(sa, skip_ws(sa, kend) + 1)
            local key = sub(sa, j + 1, kend - 2)
            seen[key] = true
            if first then
                first = false
            else
                out[#out + 1] = ', '
            end
            out[#out + 1] = sub(sa, j, kend - 1)
            out[#out + 1] = ': '
            local bv = bindex[key]
            local vend
            if bv then
                merge_into(out, sa, v, sb, bv)
                vend = skip_value(sa, v)
            else
                -- emit already measured the value, so don't skip it a second time
                vend = emit(sa, v, out)
            end
            if not vend then
                break
            end
            j = skip_ws(sa, vend)
            if byte(sa, j) ~= COMMA then
                break
            end
            j = skip_ws(sa, j + 1)
        end
    end

    for i = 1, m do
        if not seen[bkey[i]] then
            if first then
                first = false
            else
                out[#out + 1] = ', '
            end
            out[#out + 1] = sub(sb, bkf[i], bkt[i] - 1)
            out[#out + 1] = ': '
            emit(sb, bvf[i], out)
        end
    end
    out[#out + 1] = '}'
end

function run(ctx)
    local n = exa.meta.input_column_count
    if n < 2 then
        error('JSON_MERGE_PRESERVE requires at least 2 arguments')
    end
    local args = {}
    for i = 1, n do
        local s = ctx[i]
        -- A non-string argument is not a JSON document, so it merges to NULL.
        if s == null or type(s) ~= 'string' then
            return null
        end
        if not pcall(cjson.decode, s) then
            -- Retry against just the first value, matching MariaDB's leniency
            -- documented at first_value().
            s = first_value(s)
            if s == nil or not pcall(cjson.decode, s) then
                return null
            end
        end
        args[i] = s
    end

    local acc = args[1]
    for i = 2, n do
        local out = {}
        merge_into(out, acc, skip_ws(acc, 1), args[i], skip_ws(args[i], 1))
        acc = table.concat(out)
    end
    -- A single-document "merge" never happens (n >= 2), so acc is always the
    -- normalized output of at least one merge_into.
    return acc
end
/

-- === udfs/json/json_object.sql ===
--/
CREATE OR REPLACE LUA SCALAR SCRIPT UTIL.JSON_OBJECT(...)
RETURNS VARCHAR(2000000) AS

-- MariaDB JSON_OBJECT(key, value[, key, value ...]) semantics:
--   - builds a JSON object from key/value pairs, in argument order.
--   - odd number of arguments -> error (matches MariaDB's syntax requirement).
--   - no arguments            -> '{}'.
--   - NULL key                -> error.
--   - NULL value              -> JSON null.
--   - duplicate keys          -> last value wins, at the FIRST key's position.
--
-- Separators are ', ' and ': ', matching MariaDB 11.8. Note MariaDB is
-- inconsistent between its own JSON functions and uses a bare ':' for
-- JSON_OBJECTAGG; see the separator block in udfs/json/json_objectagg.sql.
--
-- KNOWN LIMITATION (Lua-only): DATE and TIMESTAMP arguments are rejected by Exasol
-- before run() is ever entered -- "Feature not supported: Lua script input type not
-- supported DATE". Verified against Exasol 2025.1.8: this is not specific to the
-- variadic `(...)` signature as the note in udfs/string/field.sql suggests; a
-- fixed-arity LUA script with a declared `d DATE` parameter is rejected
-- identically. A VARCHAR-declared parameter *does* accept a DATE argument by
-- implicit cast, but a variadic script declares no types, so no implicit cast
-- happens. Callers therefore need CAST(d AS VARCHAR(30)) at the call site. Note
-- the implicit cast would not have been transparent either: Exasol renders a
-- TIMESTAMP as '2026-04-24 16:20:00.000000'. Same trade-off ELT and FIELD accepted.
--
-- Scalar rendering (same reasoning as udfs/json/json_extract.sql):
--   - DECIMAL arrives as userdata whose tostring() is its exact decimal text, so
--     it is emitted verbatim and values wider than a double keep their precision.
--     Lua's decimal text drops trailing zeros, so DECIMAL(5,2) 3.10 emits 3.1.
--   - control characters in strings are escaped \uXXXX with UPPERCASE hex, matching
--     MariaDB 11.8 and udfs/json/json_quote.sql.
--   - non-ASCII passes through raw as UTF-8, never \u-escaped.
--
-- Nested JSON: a string value whose first character is '{' or '[' and which parses
-- as JSON is embedded as JSON rather than re-quoted as a string, so a nested
-- UTIL.JSON_OBJECT / JSON_EXTRACT / JSON_MERGE_PRESERVE / JSON_OBJECTAGG composes
-- instead of producing escaped text. Bare literals ('true', 'null', '123') are NOT
-- parsed -- that would change the meaning of user-supplied scalar strings. A caller
-- who genuinely supplies a '{'-leading string of valid JSON will see it treated as
-- JSON, which matches MariaDB's implicit JSON typing.
-- The nested document is embedded VERBATIM, which is what MariaDB does -- it does
-- not re-format a document produced by an inner function, so the inner function's
-- own spacing survives:
--     JSON_OBJECT('x', (SELECT JSON_OBJECTAGG(k,v) FROM d))
--         -> {"x": {"alpha":"2026-01-15", "beta":"2026-02-20"}}
-- Verbatim embedding also preserves each nested scalar's original spelling, so 1e2
-- stays 1e2 and wide integers keep their digits. It is why this UDF needs no JSON
-- scanner: cjson establishes that the candidate is well-formed and the source text
-- is then used as is.
--
-- Lua/Exasol boundary notes:
--   - ctx is 1-BASED, so pairs are (ctx[1], ctx[2]), (ctx[3], ctx[4]), ...
--   - SQL NULL is the `null` userdata, not nil -- test `== null`, never `== nil`.
--   - Arg types map to Lua as: DECIMAL/INT -> userdata (tonumber(v) is nil,
--     tostring(v) gives the decimal text), DOUBLE -> number, VARCHAR/CHAR ->
--     string, BOOLEAN -> boolean.
--   - RETURNS VARCHAR, so a Lua string returns directly; none of the decimal(n)
--     wrapping udfs/string/field.sql needs applies here.
--
-- cjson's acceptance when validating a nested candidate allows NaN/Infinity and
-- leading zeros, and it enforces a 1000-level nesting limit, so a document nested
-- deeper than that is treated as a plain string.

local cjson = require('cjson')
local byte, find, format, gsub, concat =
    string.byte, string.find, string.format, string.gsub, table.concat

local LBRACE, LBRACKET = 123, 91

local SHORT = {
    ['"']  = '\\"',
    ['\\'] = '\\\\',
    ['\b'] = '\\b',
    ['\f'] = '\\f',
    ['\n'] = '\\n',
    ['\r'] = '\\r',
    ['\t'] = '\\t',
}

local function escape_char(c)
    return SHORT[c] or format('\\u%04X', byte(c))
end

-- Quote as a JSON string literal. Only ASCII control characters, '"' and '\' are
-- matched, so UTF-8 continuation bytes (>= 0x80) survive intact.
local function quote(s)
    return '"' .. gsub(s, '[\0-\31"\\]', escape_char) .. '"'
end

-- Shortest text that reads back as the same double. Lua's own tostring uses %.14g,
-- which loses round-trip fidelity (1/3 would emit as 0.33333333333333).
local function double_text(v)
    if v ~= v then
        return 'NaN'
    elseif v == math.huge then
        return 'Infinity'
    elseif v == -math.huge then
        return '-Infinity'
    end
    for p = 14, 17 do
        local t = format('%.' .. p .. 'g', v)
        if tonumber(t) == v then
            -- An integral double renders with a trailing '.0'; %g omits it.
            if not find(t, '[%.eE]') then
                t = t .. '.0'
            end
            return t
        end
    end
end

local function value_text(v)
    if v == null then
        return 'null'
    end
    local t = type(v)
    if t == 'boolean' then
        return v and 'true' or 'false'
    elseif t == 'number' then
        return double_text(v)
    elseif t == 'string' then
        local c = byte(v, 1)
        if (c == LBRACE or c == LBRACKET) and pcall(cjson.decode, v) then
            return v
        end
        return quote(v)
    end
    -- DECIMAL and every other numeric userdata: exact decimal text, emitted as is.
    return tostring(v)
end

function run(ctx)
    local n = exa.meta.input_column_count
    if n % 2 ~= 0 then
        error('JSON_OBJECT requires an even number of arguments (key-value pairs)')
    end

    -- Ordered key list plus a position index, so a repeated key overwrites in place
    -- instead of appending.
    local keys, vals, pos = {}, {}, {}
    for i = 1, n, 2 do
        local k = ctx[i]
        if k == null then
            error('JSON_OBJECT key must not be NULL')
        end
        k = (type(k) == 'string') and k or tostring(k)
        local at = pos[k]
        if not at then
            at = #keys + 1
            keys[at] = k
            pos[k] = at
        end
        vals[at] = value_text(ctx[i + 1])
    end

    local out = {}
    for i = 1, #keys do
        out[i] = quote(keys[i]) .. ': ' .. vals[i]
    end
    return '{' .. concat(out, ', ') .. '}'
end
/

-- === udfs/json/json_objectagg.sql ===
--/
CREATE OR REPLACE LUA SCALAR SCRIPT UTIL.JSON_OBJECTAGG(s VARCHAR(2000000))
RETURNS VARCHAR(2000000) AS

-- MariaDB JSON_OBJECTAGG(key, value) aggregates rows into a single JSON object.
-- Exasol implements user-defined aggregates as SET SCRIPTs, but emitting SET
-- SCRIPTs cannot appear inside any expression context (scalar subqueries,
-- argument positions, CTE referenced from an outer expression -- all rejected
-- with "emitting function in expression"). MariaDB JSON_OBJECTAGG routinely
-- appears inside JSON_OBJECT(...) or as a scalar subquery, so a SET SCRIPT
-- wouldn't cover real workloads.
--
-- Workaround: the preprocessor rewrites MariaDB-form JSON_OBJECTAGG(k, v) into
--   UTIL.JSON_OBJECTAGG(LISTAGG(UTIL.JSON_OBJECT(k, v), ','))
-- LISTAGG is a standard SQL aggregate (expression-safe). It concatenates each
-- row's mini JSON object -- produced by UTIL.JSON_OBJECT, which handles type
-- coercion, JSON nesting, and NULL-key errors -- into one comma-joined string.
-- This UDF then wraps that string in [...] to make a JSON array and merges the
-- per-row objects into one.
--
-- Semantics:
--   - Empty group -> LISTAGG returns NULL -> return NULL. Matches MariaDB.
--   - NULL key -> UTIL.JSON_OBJECT raises -> error propagates. Matches MariaDB.
--   - NULL value -> embedded as JSON `null`. Matches MariaDB.
--   - Duplicate keys -> last value wins, at the FIRST key's position. Matches
--     MariaDB's "rows processed in unspecified order, later one wins" behavior.
--   - Aggregation order is whatever LISTAGG produces (no WITHIN GROUP ORDER BY
--     added by the preprocessor, so unspecified); same as MariaDB.
--
-- SEPARATORS follow MariaDB, which is inconsistent between its own JSON functions.
-- Verified on MariaDB 11.8:
--     JSON_OBJECT('a',1,'b','x')  -> {"a": 1, "b": "x"}    colon + space
--     JSON_EXTRACT('{"b":2}','$') -> {"b": 2}              colon + space
--     JSON_OBJECTAGG(k,v)         -> {"a":1, "b":2}        colon, NO space
-- So this UDF emits '":"' with no space, but still ', ' between pairs.
--
-- Values are embedded VERBATIM, which is also what MariaDB does -- it does not
-- re-format a nested document, so a nested object keeps whatever spacing the
-- function that produced it used:
--     JSON_OBJECTAGG(k, JSON_OBJECT('n',1))  -> {"alpha":{"n": 1}}
-- Embedding verbatim additionally preserves each scalar's original spelling, so
-- 1e2 stays 1e2 and integers wider than a double keep their digits, rather than
-- being round-tripped through a float.
--
-- There is NO DATE/TIMESTAMP limitation here: this script is fixed-arity with a
-- single declared VARCHAR parameter, so it never sees a date-typed argument. The
-- restriction that applies to LUA scripts lands on UTIL.JSON_OBJECT instead, one
-- level down in the rewrite -- see the KNOWN LIMITATION block in
-- udfs/json/json_object.sql, and note the CAST it requires must therefore be
-- applied to JSON_OBJECTAGG's own value argument.
--
-- WHY THIS SCANS TEXT INSTEAD OF DECODING (same reasoning as
-- udfs/json/json_extract.sql): cjson has no key order, turns every number into a
-- double, and escapes '/' as '\/', so a decode/re-encode round trip cannot
-- reproduce the input's key order or scalar spelling. Instead cjson.decode
-- validates the document and its result is discarded, then the source text is
-- scanned and each merged value copied out as is.
--
-- Lua/Exasol boundary notes:
--   - SQL NULL is the `null` userdata, not nil -- test `== null`, never `== nil`.
--   - RETURNS VARCHAR, so a Lua string returns directly.
--
-- Known limitations, both from scanning raw text and both shared with
-- udfs/json/json_extract.sql:
--   - keys are compared by their raw source text, so two keys that differ in
--     spelling but denote the same string ("a" and "a") are treated as
--     distinct. UTIL.JSON_OBJECT never emits \u escapes in a key unless the key
--     genuinely contains a control character, so this cannot arise from the
--     preprocessor's own rewrite.
--   - cjson's acceptance allows NaN/Infinity and leading zeros, and it enforces a
--     1000-level nesting limit.

local cjson = require('cjson')
local byte, find, sub, concat = string.byte, string.find, string.sub, table.concat

local QUOTE, LBRACE, LBRACKET, RBRACE, RBRACKET = 34, 123, 91, 125, 93
local SPACE, TAB, LF, CR = 32, 9, 10, 13
local LOWER_U = 117

local function skip_ws(s, i)
    local c = byte(s, i)
    while c == SPACE or c == TAB or c == LF or c == CR do
        i = i + 1
        c = byte(s, i)
    end
    return i
end

-- Index just past the closing quote of the string starting at i. Jumps quote to
-- quote in C; only a backslash forces a per-escape step.
local function scan_string(s, i)
    local j = i + 1
    while true do
        local k = find(s, '["\\]', j)
        if not k then
            return nil
        end
        if byte(s, k) == QUOTE then
            return k + 1
        end
        j = (byte(s, k + 1) == LOWER_U) and k + 6 or k + 2
    end
end

-- Index just past the value starting at i (which must be non-whitespace). Assumes
-- the document already validated, so this only measures extent.
local function skip_value(s, i)
    local c = byte(s, i)
    if c == QUOTE then
        return scan_string(s, i)
    end
    if c == LBRACE or c == LBRACKET then
        local depth = 0
        local j = i
        while true do
            local k = find(s, '[%[%]{}"]', j)
            if not k then
                return nil
            end
            local ch = byte(s, k)
            if ch == QUOTE then
                j = scan_string(s, k)
                if not j then
                    return nil
                end
            else
                if ch == LBRACE or ch == LBRACKET then
                    depth = depth + 1
                else
                    depth = depth - 1
                    if depth == 0 then
                        return k + 1
                    end
                end
                j = k + 1
            end
        end
    end
    -- Scalar: numbers and true/false/null contain no structural character, so the
    -- value ends at the next one (or at end of document for a bare scalar).
    local k = find(s, '[,%]}]', i)
    local e = (k or #s + 1) - 1
    local b = byte(s, e)
    while b == SPACE or b == TAB or b == LF or b == CR do
        e = e - 1
        b = byte(s, e)
    end
    return e + 1
end

-- Merge the object starting at i (byte(s, i) == '{') into the ordered accumulator.
-- Returns the index just past the object's closing brace.
local function merge_object(s, i, keys, vals, pos)
    local j = skip_ws(s, i + 1)
    if byte(s, j) == RBRACE then
        return j + 1
    end
    while true do
        local kend = scan_string(s, j)
        local key = sub(s, j, kend - 1)          -- raw text, quotes included
        j = skip_ws(s, skip_ws(s, kend) + 1)     -- step over the ':'
        local vend = skip_value(s, j)
        local at = pos[key]
        if not at then
            at = #keys + 1
            keys[at] = key
            pos[key] = at
        end
        vals[at] = sub(s, j, vend - 1)
        j = skip_ws(s, vend)
        if byte(s, j) == RBRACE then
            return j + 1
        end
        j = skip_ws(s, j + 1)
    end
end

function run(ctx)
    local s = ctx.s
    if s == null then
        return null
    end

    -- Bracket LISTAGG's comma-joined objects into one JSON array. Validation is
    -- cjson's job and its result is discarded.
    local doc = '[' .. s .. ']'
    if not pcall(cjson.decode, doc) then
        error('JSON_OBJECTAGG could not parse the aggregated JSON objects')
    end

    local keys, vals, pos = {}, {}, {}
    local i = skip_ws(doc, 2)
    if byte(doc, i) ~= RBRACKET then
        while true do
            if byte(doc, i) ~= LBRACE then
                error('JSON_OBJECTAGG expects each aggregated element to be a JSON object')
            end
            i = skip_ws(doc, merge_object(doc, i, keys, vals, pos))
            if byte(doc, i) == RBRACKET then
                break
            end
            i = skip_ws(doc, i + 1)
        end
    end

    local out = {}
    for n = 1, #keys do
        out[n] = keys[n] .. ':' .. vals[n]
    end
    return '{' .. concat(out, ', ') .. '}'
end
/

-- === udfs/json/json_quote.sql ===
--/
CREATE OR REPLACE LUA SCALAR SCRIPT UTIL.JSON_QUOTE(
    val VARCHAR(2000000)
) RETURNS VARCHAR(2000000) AS

-- MariaDB JSON_QUOTE semantics: wrap the argument as a JSON string literal,
-- escaping interior quotes and control characters.
--   NULL          -> NULL
--   'hello'       -> '"hello"'
--   'a"b'         -> '"a\"b"'           (interior " escaped)
--   'a' + LF +'b' -> '"a\nb"'           (control chars escaped)
--   'null'        -> '"null"'           (no JSON parsing; always a string)
-- Inverse of UTIL.JSON_UNQUOTE for string inputs.
--
-- Exasol quirk: VARCHAR '' is indistinguishable from NULL at the UDF boundary
-- (Exasol treats '' IS NULL as TRUE), so JSON_QUOTE('') returns NULL on Exasol
-- even though MariaDB returns '""'. This is a platform-level limitation, not a
-- UDF bug -- the run() body would otherwise produce '""' on a literal ''.
--
-- The escape table is hand-rolled rather than delegated to cjson.encode:
-- cjson escapes '/' as '\/' (MariaDB leaves it bare) and gives no control over
-- \u letter case. The set below is byte-exact with MariaDB 11.8:
--   " \ BS TAB LF FF CR  -> two-char short forms
--   other 0x00-0x1F      -> \uXXXX with UPPERCASE hex digits
--   0x7F (DEL)           -> passed through raw (MariaDB does not escape it)
--   non-ASCII            -> passed through raw as UTF-8 (no \u escaping)
-- Only ASCII bytes are matched, so UTF-8 continuation bytes (>= 0x80) are
-- never touched and multi-byte characters survive intact.

local SHORT = {
    ['"']  = '\\"',
    ['\\'] = '\\\\',
    ['\b'] = '\\b',
    ['\f'] = '\\f',
    ['\n'] = '\\n',
    ['\r'] = '\\r',
    ['\t'] = '\\t',
}

local function escape(c)
    return SHORT[c] or string.format('\\u%04X', string.byte(c))
end

function run(ctx)
    local s = ctx.val
    if s == null then
        return null
    end
    local body = string.gsub(s, '[\0-\31"\\]', escape)
    return '"' .. body .. '"'
end
/

-- === udfs/json/json_unquote.sql ===
--/
CREATE OR REPLACE LUA SCALAR SCRIPT UTIL.JSON_UNQUOTE(
    val VARCHAR(2000000)
) RETURNS VARCHAR(2000000) AS

-- MariaDB JSON_UNQUOTE semantics:
--   NULL                 -> NULL
--   '"hello"'            -> 'hello'             (JSON string -> unescaped text)
--   '"a\\nb"'            -> 'a' + LF + 'b'      (JSON escapes resolved)
--   anything else        -> input unchanged     (numbers, objects, arrays,
--                                                already-unquoted text, garbage)
--
-- MariaDB does NOT run a strict JSON parse here -- it runs a lenient scan of a
-- single leading string token. The rules below were derived by probing MariaDB
-- 11.8 directly, because the differences from a strict parse are not documented
-- and are not reproducible with cjson (which rejects trailing garbage and
-- unknown escapes that MariaDB accepts). Hence the hand-rolled scanner:
--
--   skip leading whitespace         ' "a"'        -> 'a'
--   ignore ALL trailing content     '"a" junk'    -> 'a'   ('""x' -> '')
--   first non-space not '"'         'x"a"'        -> unchanged (no attempt)
--   unknown escape drops backslash  '"a\qb"'      -> 'aqb'
--   \uXXXX, case-insensitive hex    '"café"' -> 'café'
--   surrogate pairs combine         '"😀"' -> the astral character
--
-- The scan FAILS (returning the input unchanged) on any of:
--   no closing quote                '"unterminated', '"a\"'
--   raw control byte < 0x20 inside  '"a' + TAB + 'b"'  (also when escaped:
--                                   backslash + raw TAB fails identically)
--   \u not followed by 4 hex digits '"a\u00zzb"', '"a\u041"'
--   an unpaired surrogate           '"\ud83d"', '"\ude00"'
-- 0x7F (DEL) is NOT a failure -- MariaDB permits it raw inside the quotes.

local SIMPLE = {
    ['"']  = '"',
    ['\\'] = '\\',
    ['/']  = '/',
    ['b']  = '\b',
    ['f']  = '\f',
    ['n']  = '\n',
    ['r']  = '\r',
    ['t']  = '\t',
}

-- Codepoint from the 4 hex digits at s[i..i+3], or nil if they aren't 4 hex.
local function hex4(s, i)
    local h = string.sub(s, i, i + 3)
    if #h < 4 or not string.match(h, '^%x%x%x%x$') then
        return nil
    end
    return tonumber(h, 16)
end

-- Scan the JSON string token that starts at s[i] (known to be '"').
-- Returns the decoded text, or nil if the token is malformed.
local function scan(s, i)
    local out = {}
    i = i + 1
    while true do
        -- Jump straight to the next byte that needs handling and copy the run of
        -- ordinary characters before it in one piece. Iterating per character
        -- instead costs ~5x on strings that contain escapes.
        local j = string.find(s, '["\\\0-\31]', i)
        if not j then
            return nil                                -- ran out before the closing quote
        end
        if j > i then
            out[#out + 1] = string.sub(s, i, j - 1)
        end
        i = j
        local c = string.sub(s, i, i)
        if c == '"' then
            return table.concat(out)                  -- trailing content ignored
        elseif string.byte(c) < 32 then
            return nil                                -- raw control byte
        else                                          -- c == '\\'
            local e = string.sub(s, i + 1, i + 1)
            if e == '' then
                return nil                            -- trailing lone backslash
            elseif e == 'u' then
                local cp = hex4(s, i + 2)
                if not cp then
                    return nil
                end
                i = i + 6
                if cp >= 0xD800 and cp <= 0xDBFF then
                    -- high surrogate: require a following low surrogate
                    if string.sub(s, i, i + 1) ~= '\\u' then
                        return nil
                    end
                    local lo = hex4(s, i + 2)
                    if not lo or lo < 0xDC00 or lo > 0xDFFF then
                        return nil
                    end
                    cp = 0x10000 + (cp - 0xD800) * 0x400 + (lo - 0xDC00)
                    i = i + 6
                elseif cp >= 0xDC00 and cp <= 0xDFFF then
                    return nil                        -- unpaired low surrogate
                end
                out[#out + 1] = utf8.char(cp)
            elseif string.byte(e) < 32 then
                return nil                            -- escaping a raw control byte fails too
            else
                out[#out + 1] = SIMPLE[e] or e        -- unknown escape: drop the backslash
                i = i + 2
            end
        end
    end
end

function run(ctx)
    local s = ctx.val
    if s == null then
        return null
    end

    local i = 1
    while i <= #s and string.find(string.sub(s, i, i), '^[ \t\n\r]') do
        i = i + 1
    end
    if string.sub(s, i, i) ~= '"' then
        return s
    end

    -- Fast path: with no backslash anywhere there are no escapes to resolve, so
    -- the token is just the span to the next quote. Avoids the per-character
    -- loop for the overwhelmingly common case of ordinary quoted text.
    if not string.find(s, '\\', i, true) then
        local j = string.find(s, '"', i + 1, true)
        if not j then
            return s
        end
        local body = string.sub(s, i + 1, j - 1)
        if string.find(body, '[\0-\31]') then
            return s
        end
        return body
    end

    local v = scan(s, i)
    if v == nil then
        return s
    end
    return v
end
/

-- === udfs/meta/get_glot_version.sql ===
--/
CREATE OR REPLACE PYTHON3 SCALAR SCRIPT UTIL.GET_GLOT_VERSION()
RETURNS VARCHAR(64) AS

# Returns the sqlglot version string visible to the active SCRIPT_LANGUAGES
# SLC. Lets tests confirm they're hitting the SLC they expect — some preprocessor
# rewrites (e.g. USE -> OPEN SCHEMA from sqlglot PR #7538) only work on SLCs
# whose bundled sqlglot is recent enough.

import sqlglot


def run(ctx):
    return getattr(sqlglot, "__version__", "unknown")
/

-- === udfs/string/elt.sql ===
--/
CREATE OR REPLACE LUA SCALAR SCRIPT UTIL.ELT(...)
RETURNS VARCHAR(2000000) AS

-- MariaDB ELT(N, str1[, str2, ...]) semantics:
--   - 1-based pick: ELT(1, 'a', 'b', 'c') -> 'a', ELT(2, ...) -> 'b'.
--   - N is NULL          -> NULL.
--   - N < 1 or N > count -> NULL.
--   - Selected element itself NULL -> NULL.
--   - Fractional N follows MariaDB's INT-conversion rules, which differ by the
--     argument's declared type (verified against MariaDB 11.8):
--       numeric N (DECIMAL/DOUBLE) rounds half away from zero
--                              -> ELT(2.7, 'a','b','c') = 'c', ELT(2.5, ...) = 'c'
--       string N               truncates toward zero
--                              -> ELT('2.9', 'a','b','c') = 'b', ELT('0.9', ...) = NULL
--   - Non-numeric N (e.g. an arbitrary string) -> NULL conservatively.
-- Requires at least 2 args (one index + one string); fewer raises (matches MariaDB syntax).
--
-- KNOWN LIMITATION (Lua-only): Exasol rejects DATE and TIMESTAMP inputs to a LUA
-- script declared with a variadic `(...)` signature -- "Feature not supported: Lua
-- script input type not supported DATE". A parameter declared with a type gets an
-- implicit cast to it, so a VARCHAR-declared parameter accepts a DATE argument
-- (UTIL.JSON_QUOTE takes a DATE fine), but `(...)` declares no type to cast to.
-- Note that declaring the DATE type itself does not help either: a fixed-arity LUA
-- script with a `d DATE` parameter is rejected identically. So
-- ELT(1, DATE '2020-01-01') raises. Accepted deliberately: ELT picks among string
-- arguments, so date args are a corner case, and the failure is a loud error rather
-- than a wrong answer -- CAST(d AS VARCHAR(...)) at the call site is the
-- workaround. BOOLEAN args are unaffected. UTIL.JSON_OBJECT hit the same wall and
-- accepted the same trade-off; see the KNOWN LIMITATION block there.
--
-- Lua/Exasol boundary notes:
--   - ctx is 1-BASED, so the index is ctx[1] and strn is ctx[n + 1].
--   - DECIMAL args arrive as userdata, not Lua numbers: tonumber(v) yields nil
--     and math.floor(v) raises. tostring(v) gives the decimal text, so the
--     coercion below round-trips through tostring for every non-string type.
--     (DOUBLE args do arrive as Lua numbers; the same path handles them.)
--   - SQL NULL is the `null` userdata, not nil, and tostring(null) is an
--     address string -- so `== null` must be tested before any coercion.

function run(ctx)
    local n_args = exa.meta.input_column_count
    if n_args < 2 then
        error('ELT requires at least 2 arguments (index and one string)')
    end
    local raw = ctx[1]
    if raw == null then
        return null
    end
    -- Lua's own type distinguishes the two rounding rules: only a VARCHAR/CHAR
    -- arg arrives as a Lua string, so `type(raw) == 'string'` is exactly
    -- MariaDB's "string operand" case (truncate); DECIMAL userdata and DOUBLE
    -- numbers both take the round-half-away-from-zero path.
    local n = tonumber(tostring(raw))
    if n == nil then
        return null
    end
    if type(raw) == 'string' then
        n = n >= 0 and math.floor(n) or math.ceil(n)
    else
        n = n >= 0 and math.floor(n + 0.5) or math.ceil(n - 0.5)
    end
    local string_count = n_args - 1
    if n < 1 or n > string_count then
        return null
    end
    local val = ctx[n + 1]
    if val == null then
        return null
    end
    return tostring(val)
end
/

-- === udfs/string/field.sql ===
--/
CREATE OR REPLACE LUA SCALAR SCRIPT UTIL.FIELD(...)
RETURNS INT AS

-- MariaDB FIELD(str, str1[, str2, ...]) semantics:
--   - 1-based search: returns the index of `str` in the list, or 0 if not found.
--   - str is NULL          -> 0 (NULL never equals NULL, so it's never "found").
--   - List element NULL    -> skipped, never matches.
--   - Only `str` provided (no list) -> 0.
-- Comparison mode follows MySQL/MariaDB's documented three-way rule, verified
-- against MariaDB 11.8:
--   - all args are strings  -> compare as strings, NO numeric coercion, so
--                              FIELD('1', '01') = 0.
--   - all args are numbers  -> compare as numbers (BOOLEAN counts as a number:
--                              FIELD(1, TRUE) = 1).
--   - anything mixed        -> compare EVERY arg as a double. A string's value is
--                              its leading numeric prefix and 0 when there is
--                              none, which is why FIELD('x', 0, 'y') = 1 and
--                              FIELD('12abc', 12) = 1.
-- The mixed rule produces matches that look surprising in isolation -- an earlier
-- version of this UDF deliberately refused to implement it and used string
-- comparison throughout -- but it is what MariaDB does, so transpiled queries
-- need it to agree.
--
-- Exasol quirk (platform-level, same as the one noted in udfs/json/json_quote.sql):
-- VARCHAR '' is indistinguishable from NULL at the UDF boundary because Exasol
-- treats '' IS NULL as TRUE. So FIELD('', 0) returns 0 here where MariaDB coerces
-- '' to 0 and answers 1 -- the empty string never reaches run() as a string. Not
-- fixable inside the UDF.
--
-- KNOWN DIVERGENCE: the all-strings path compares case-SENSITIVELY. MariaDB's
-- answer there depends on collation (the default utf8mb4_general_ci makes
-- FIELD('a', 'A') = 1; a _bin or _cs collation makes it 0), and a UDF cannot see
-- the collation of its arguments, so there is no single correct behaviour to copy.
-- Case-sensitive matches Exasol's own default comparison semantics.
--
-- KNOWN LIMITATION (Lua-only): Exasol rejects DATE and TIMESTAMP inputs to a LUA
-- script declared with a variadic `(...)` signature -- "Feature not supported: Lua
-- script input type not supported DATE". See the same block in udfs/string/elt.sql
-- for the full reasoning; CAST(d AS VARCHAR(...)) at the call site is the
-- workaround.
--
-- Lua/Exasol boundary notes:
--   - ctx is 1-BASED, so the needle is ctx[1] and the list is ctx[2..n].
--   - SQL NULL is the `null` userdata, not nil -- test `== null`, never `== nil`.
--   - Arg types map to Lua as: DECIMAL -> userdata (tonumber(v) is nil, but
--     tostring(v) gives the decimal text), DOUBLE -> number, VARCHAR/CHAR ->
--     string, BOOLEAN -> boolean. `type(v) == 'string'` is therefore the mode
--     test: it distinguishes a SQL string arg from every numeric arg.
--   - Lua's decimal text drops trailing zeros (DECIMAL(4,2) 2.00 -> '2'). Harmless
--     here because a decimal only ever meets a string in mixed mode, which compares
--     numerically, never as text.
--   - RETURNS INT must be satisfied with decimal(n), not a plain Lua number:
--     `return 0` fails at runtime with "bad argument (decimal expected, got
--     number)", and a string is rejected the same way. UTIL.ELT needed none of
--     this because it returns VARCHAR, where Lua strings pass straight through.

-- MySQL's string-to-double conversion keeps the longest leading numeric prefix
-- and yields 0 when there is none: '12abc' -> 12, ' 3 ' -> 3, '1e2' -> 100,
-- '.5' -> 0.5, '+2' -> 2, '0x10' -> 0 (no hex parsing), '' -> 0. Lua's tonumber
-- rejects all of the prefixed forms outright, so match the prefix explicitly.
-- Ordered longest-form first: exponent forms before plain digits, so '1e2' does
-- not stop at '1'.
local NUM_PREFIX = {
    '^%s*[-+]?%d+%.?%d*[eE][-+]?%d+',
    '^%s*[-+]?%.%d+[eE][-+]?%d+',
    '^%s*[-+]?%d+%.?%d*',
    '^%s*[-+]?%.%d+',
}

local function str2double(s)
    for _, pat in ipairs(NUM_PREFIX) do
        local m = string.match(s, pat)
        if m then
            local n = tonumber(m)
            if n then
                return n
            end
        end
    end
    return 0
end

local function numval(v)
    if type(v) == 'boolean' then
        return v and 1 or 0
    end
    if type(v) == 'string' then
        return str2double(v)
    end
    return tonumber(tostring(v))
end

function run(ctx)
    local n_args = exa.meta.input_column_count
    if n_args < 1 then
        error('FIELD requires at least 1 argument (the search value)')
    end
    local needle = ctx[1]
    if needle == null then
        return decimal(0)
    end
    if n_args == 1 then
        return decimal(0)
    end

    -- NULLs never match, so they also never influence the mode choice.
    local all_strings = type(needle) == 'string'
    if all_strings then
        for i = 2, n_args do
            local v = ctx[i]
            if v ~= null and type(v) ~= 'string' then
                all_strings = false
                break
            end
        end
    end

    if all_strings then
        for i = 2, n_args do
            local v = ctx[i]
            if v ~= null and v == needle then
                return decimal(i - 1)
            end
        end
        return decimal(0)
    end

    local n = numval(needle)
    for i = 2, n_args do
        local v = ctx[i]
        if v ~= null and numval(v) == n then
            return decimal(i - 1)
        end
    end
    return decimal(0)
end
/

-- === preprocessor/maria_preprocessor.sql ===
CREATE OR REPLACE PYTHON3 PREPROCESSOR SCRIPT UTIL.MARIA_PREPROCESSOR AS

import json
import re
import sqlglot
from sqlglot import expressions as exp


_PREPROCESSOR_VERSION = "2026.8.0"
_PREPROCESSOR_BUILD = "773baaa-dirty"


def adapter_call(request):
    try:
        return _transpile(request)
    except Exception:
        return request


_SYSVAR_VALUES = {
    "max_allowed_packet": "16777216",
    "auto_increment_increment": "1",
    "system_time_zone": "UTC",
    "time_zone": "+00:00",
    "lower_case_table_names": "2",
    "sql_mode": "STRICT_TRANS_TABLES",
}

_VERSION_VAR = "maria_preprocessor_version"


def _sysvar_key(sp):
    return sp.name.lstrip("@").lower()


def _sysvar_value(key):
    if key == _VERSION_VAR:
        return _PREPROCESSOR_VERSION + "_" + _PREPROCESSOR_BUILD
    return _SYSVAR_VALUES.get(key)


def _rewrite_session_var_select(tree):
    if not isinstance(tree, exp.Select):
        return None
    projs = tree.expressions
    if not projs or not all(isinstance(e, exp.SessionParameter) for e in projs):
        return None
    cols = []
    for sp in projs:
        val = _sysvar_value(_sysvar_key(sp))
        if val is None:
            lit = "NULL"
        elif val.isdigit():
            lit = val
        else:
            lit = "'" + val.replace("'", "''") + "'"
        alias = sp.sql(dialect="mysql").replace('"', '""')
        cols.append(lit + ' AS "' + alias + '"')
    return "SELECT " + ", ".join(cols)


def _sql_string(value):
    return "'" + value.replace("'", "''") + "'"


def _rewrite_show_variables(tree):
    if not isinstance(tree, exp.Show) or tree.name != "VARIABLES":
        return None
    if tree.args.get("where") is not None:
        return None

    rows = ", ".join(
        "(" + _sql_string(name) + ", " + _sql_string(value) + ")"
        for name, value in sorted(_SYSVAR_VALUES.items()))
    sql = ('SELECT * FROM (VALUES ' + rows
           + ') AS t("Variable_name", "Value")')

    like = tree.args.get("like")
    if like is not None:
        sql += ' WHERE UPPER("Variable_name") LIKE UPPER(' + _sql_string(like.name) + ')'
    return sql


_CHARSETS = (
    ("ascii", "US ASCII", "ascii_general_ci", 1),
    ("utf8mb4", "UTF-8 Unicode", "utf8mb4_general_ci", 4),
)


def _rewrite_show_charset(tree):
    if not isinstance(tree, exp.Show) or tree.name != "CHARACTER SET":
        return None
    if tree.args.get("where") is not None:
        return None

    rows = ", ".join(
        "(" + _sql_string(name) + ", " + _sql_string(desc) + ", "
        + _sql_string(collation) + ", " + str(maxlen) + ")"
        for name, desc, collation, maxlen in _CHARSETS)
    sql = ('SELECT * FROM (VALUES ' + rows
           + ') AS t("Charset", "Description", "Default collation", "Maxlen")')

    like = tree.args.get("like")
    if like is not None:
        sql += ' WHERE UPPER("Charset") LIKE UPPER(' + _sql_string(like.name) + ')'
    return sql


def _rewrite_show_create_table(tree):
    if not isinstance(tree, exp.Show) or tree.name != "CREATE TABLE":
        return None
    target = tree.args.get("target")
    if target is None:
        return None
    db = tree.args.get("db")
    schema = (' AND UPPER("TABLE_SCHEMA") = ' + _sql_string(db.name.upper())
              if db is not None
              else ' AND UPPER("TABLE_SCHEMA") = UPPER(CURRENT_SCHEMA)')
    return ('SELECT "TABLE_NAME" AS "Table", "DDL" AS "Create Table"'
            + ' FROM "UTIL"."SHOW_CREATE_TABLE"'
            + ' WHERE UPPER("TABLE_NAME") = ' + _sql_string(target.name.upper())
            + schema)


def _rewrite_show_engines(tree):
    if not isinstance(tree, exp.Show) or tree.name != "ENGINES":
        return None
    return ("SELECT * FROM (VALUES ("
            + _sql_string("EXASOL") + ", " + _sql_string("DEFAULT") + ", "
            + _sql_string("Exasol analytic database") + ", "
            + _sql_string("YES") + ", " + _sql_string("NO") + ", "
            + _sql_string("NO") + ")) AS t("
            + '"Engine", "Support", "Comment", "Transactions", "XA", "Savepoints")')


def _rewrite_show_plugins(tree):
    if not isinstance(tree, exp.Show) or tree.name != "PLUGINS":
        return None
    return ("SELECT * FROM (VALUES ("
            + _sql_string("EXASOL") + ", " + _sql_string("ACTIVE") + ", "
            + _sql_string("STORAGE ENGINE") + ", CAST(NULL AS VARCHAR(64)), "
            + _sql_string("PROPRIETARY") + ")) AS t("
            + '"Name", "Status", "Type", "Library", "License")')


_COLLATIONS = (
    ("ascii_general_ci", "ascii", 11, "Yes"),
    ("utf8mb4_general_ci", "utf8mb4", 45, "Yes"),
)


def _rewrite_show_collation(tree):
    if not isinstance(tree, exp.Show) or tree.name != "COLLATION":
        return None
    if tree.args.get("where") is not None:
        return None

    rows = ", ".join(
        "(" + _sql_string(name) + ", " + _sql_string(charset) + ", "
        + str(ident) + ", " + _sql_string(default) + ", 'Yes', 1)"
        for name, charset, ident, default in _COLLATIONS)
    sql = ('SELECT * FROM (VALUES ' + rows
           + ') AS t("Collation", "Charset", "Id", "Default", "Compiled", "Sortlen")')

    like = tree.args.get("like")
    if like is not None:
        sql += ' WHERE UPPER("Collation") LIKE UPPER(' + _sql_string(like.name) + ')'
    return sql


_PROCESSLIST_COLUMNS = (
    ("ID", "Id"),
    ("USER", "User"),
    ("HOST", "Host"),
    ("DB", "db"),
    ("COMMAND", "Command"),
    ("TIME", "Time"),
    ("STATE", "State"),
    ("INFO", "Info"),
    ("PROGRESS", "Progress"),
)


def _rewrite_show_processlist(tree):
    if not isinstance(tree, exp.Show) or tree.name != "PROCESSLIST":
        return None
    cols = ", ".join('"' + src + '" AS "' + label + '"'
                     for src, label in _PROCESSLIST_COLUMNS)
    return ("SELECT " + cols
            + ' FROM "INFORMATION_SCHEMA"."PROCESSLIST"')



_TABLE_STATUS_COLUMNS = (
    ("TABLE_NAME", "Name"),
    ("ENGINE", "Engine"),
    ("VERSION", "Version"),
    ("ROW_FORMAT", "Row_format"),
    ("TABLE_ROWS", "Rows"),
    ("AVG_ROW_LENGTH", "Avg_row_length"),
    ("DATA_LENGTH", "Data_length"),
    ("MAX_DATA_LENGTH", "Max_data_length"),
    ("INDEX_LENGTH", "Index_length"),
    ("DATA_FREE", "Data_free"),
    ("AUTO_INCREMENT", "Auto_increment"),
    ("CREATE_TIME", "Create_time"),
    ("UPDATE_TIME", "Update_time"),
    ("CHECK_TIME", "Check_time"),
    ("TABLE_COLLATION", "Collation"),
    ("CHECKSUM", "Checksum"),
    ("CREATE_OPTIONS", "Create_options"),
    ("TABLE_COMMENT", "Comment"),
)


def _rewrite_show_table_status(tree):
    if not isinstance(tree, exp.Show) or tree.name != "TABLE STATUS":
        return None
    if tree.args.get("where") is not None:
        return None

    cols = ", ".join('"' + src + '" AS "' + label + '"'
                     for src, label in _TABLE_STATUS_COLUMNS)
    db = tree.args.get("db")
    schema = (_sql_string(db.name.upper()) if db is not None
              else 'UPPER(CURRENT_SCHEMA)')
    sql = ("SELECT " + cols
           + ' FROM "INFORMATION_SCHEMA"."TABLES"'
           + ' WHERE UPPER("TABLE_SCHEMA") = ' + schema)

    like = tree.args.get("like")
    if like is not None:
        sql += ' AND UPPER("TABLE_NAME") LIKE UPPER(' + _sql_string(like.name) + ')'
    return sql


_SET_STATEMENT_RE = re.compile(r"\s*SET\s+STATEMENT\s+", re.IGNORECASE)


def _skip_ws_comments(sql, i):
    n = len(sql)
    while i < n:
        ch = sql[i]
        if ch.isspace():
            i += 1
        elif ch == "#" or sql.startswith("--", i):
            j = sql.find("\n", i)
            i = n if j < 0 else j + 1
        elif sql.startswith("/*", i):
            j = sql.find("*/", i + 2)
            i = n if j < 0 else j + 2
        else:
            break
    return i


_SQL_SELECT_LIMIT_RE = re.compile(
    r"(?:^|,)\s*(?:@@)?(?:(?:session|local)\.)?sql_select_limit\s*=\s*(\d+)",
    re.IGNORECASE)


def _strip_set_statement(sql):
    m = _SET_STATEMENT_RE.match(sql, _skip_ws_comments(sql, 0))
    if not m:
        return sql, None
    i = m.end()
    n = len(sql)
    depth = 0
    quote = ""
    delim = True
    seen = []
    while i < n:
        ch = sql[i]
        if quote:
            if ch == "\\" and quote != "`":
                i += 1
            elif ch == quote:
                if i + 1 < n and sql[i + 1] == quote:
                    i += 1          # doubled quote -> escaped, stay in string
                else:
                    quote = ""
            i += 1
            continue
        j = _skip_ws_comments(sql, i)
        if j > i:
            i = j
            delim = True
            seen.append(" ")
            continue
        if ch in ("'", '"', "`"):
            quote = ch
            seen.append(" ")
        elif ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
        elif ch in ",=":
            delim = True
            seen.append(ch)
            i += 1
            continue
        elif depth == 0 and delim and sql[i:i + 3].upper() == "FOR":
            after = sql[i + 3:i + 4]
            if not (after.isalnum() or after == "_"):
                return sql[i + 3:].lstrip(), _select_limit_of("".join(seen))
        else:
            seen.append(ch)
        delim = False
        i += 1
    return sql, None


def _select_limit_of(vars_text):
    m = None
    for m in _SQL_SELECT_LIMIT_RE.finditer(vars_text):
        pass
    return int(m.group(1)) if m else None


_SET_OPERATION = getattr(exp, "SetOperation", exp.Union)


def _is_zero_literal(node):
    return isinstance(node, exp.Literal) and node.is_int and int(node.this) == 0


def _order_by_offsets(tree):
    for node in tree.find_all(exp.Select, _SET_OPERATION):
        offset = node.args.get("offset")
        if offset is None or node.args.get("order") is not None:
            continue
        if _is_zero_literal(offset.expression):
            node.set("offset", None)
            continue
        node.set("order", exp.Order(expressions=[
            exp.Ordered(this=exp.Literal.number(1))]))
    return tree


def _transpile(request):
    request, select_limit = _strip_set_statement(request)
    tree = sqlglot.parse_one(request, read="mysql")
    if tree is None:
        return request
    sysvars = _rewrite_session_var_select(tree)
    if sysvars is not None:
        return sysvars
    showvars = _rewrite_show_variables(tree)
    if showvars is not None:
        return showvars
    charset = _rewrite_show_charset(tree)
    if charset is not None:
        return charset
    collation = _rewrite_show_collation(tree)
    if collation is not None:
        return collation
    create_table = _rewrite_show_create_table(tree)
    if create_table is not None:
        return create_table
    engines = _rewrite_show_engines(tree)
    if engines is not None:
        return engines
    plugins = _rewrite_show_plugins(tree)
    if plugins is not None:
        return plugins
    procs = _rewrite_show_processlist(tree)
    if procs is not None:
        return procs
    status = _rewrite_show_table_status(tree)
    if status is not None:
        return status
    tree = tree.transform(_rewrite_to_util)
    if (select_limit is not None
            and isinstance(tree, (exp.Select, _SET_OPERATION))
            and not tree.args.get("limit")):
        tree = tree.limit(select_limit)
    tree = _order_by_offsets(tree)
    return tree.sql(dialect="exasol", identify=True)


def _rewrite_to_util(node):
    if isinstance(node, exp.SessionParameter):
        val = _sysvar_value(_sysvar_key(node))
        if val is None:
            return exp.Null()
        if val.isdigit():
            return exp.Literal.number(val)
        return exp.Literal.string(val)

    if (isinstance(node, exp.Column)
            and node.table == ""
            and node.name
            and node.name.upper() in _EXASOL_BARE_KEYWORDS):
        return exp.Var(this=node.name)

    if isinstance(node, exp.Set):
        items = node.expressions or []
        if items and all(
                isinstance(it, exp.SetItem)
                and (it.args.get("kind") in ("NAMES", "CHARACTER SET")
                     or isinstance(it.this, exp.EQ))
                for it in items):
            return exp.Command(
                this="--",
                expression=exp.Literal.string(
                    " mariadb session SET is a no-op on Exasol"),
            )

    if isinstance(node, exp.CTE):
        inner = node.this
        if isinstance(inner, exp.Select):
            _alias_unaliased_select(inner)
        elif isinstance(inner, exp.Union):
            for sub in inner.find_all(exp.Select):
                _alias_unaliased_select(sub)
        return node

    if isinstance(node, exp.JSONExtract) and not node.args.get("emits"):
        paths = []
        if node.expression is not None:
            paths.append(_strip_sql_quotes(node.expression.sql()))
        paths.extend(_strip_sql_quotes(p.sql()) for p in node.expressions)
        return exp.Anonymous(
            this="UTIL.JSON_EXTRACT",
            expressions=[node.this, exp.Literal.string(json.dumps(paths))],
        )

    if isinstance(node, exp.JSONObject):
        args = []
        for kv in node.expressions:
            k = kv.this
            v = kv.expression
            if isinstance(k, exp.Expression):
                k = k.transform(_rewrite_to_util)
            if isinstance(v, exp.Expression):
                v = v.transform(_rewrite_to_util)
            args.append(k)
            args.append(v)
        return exp.Anonymous(this="UTIL.JSON_OBJECT", expressions=args)

    if (isinstance(node, exp.Anonymous)
            and isinstance(node.this, str)
            and node.this.upper() == "JSON_OBJECTAGG"):
        new_exprs = [e.transform(_rewrite_to_util) if isinstance(e, exp.Expression) else e
                     for e in node.expressions]
        return _wrap_json_objectagg(new_exprs)

    _JSONObjectAgg = getattr(exp, "JSONObjectAgg", None)
    if _JSONObjectAgg is not None and isinstance(node, _JSONObjectAgg):
        args = []
        for kv in node.expressions:
            k = kv.this
            v = kv.expression
            if isinstance(k, exp.Expression):
                k = k.transform(_rewrite_to_util)
            if isinstance(v, exp.Expression):
                v = v.transform(_rewrite_to_util)
            args.append(k)
            args.append(v)
        return _wrap_json_objectagg(args)

    if (isinstance(node, exp.Anonymous)
            and isinstance(node.this, str)
            and node.this.upper() == "JSON_UNQUOTE"):
        new_exprs = [e.transform(_rewrite_to_util) if isinstance(e, exp.Expression) else e
                     for e in node.expressions]
        return exp.Anonymous(this="UTIL.JSON_UNQUOTE", expressions=new_exprs)

    if (isinstance(node, exp.Anonymous)
            and isinstance(node.this, str)
            and node.this.upper() == "JSON_QUOTE"):
        new_exprs = [e.transform(_rewrite_to_util) if isinstance(e, exp.Expression) else e
                     for e in node.expressions]
        return exp.Anonymous(this="UTIL.JSON_QUOTE", expressions=new_exprs)

    if (isinstance(node, exp.Anonymous)
            and isinstance(node.this, str)
            and node.this.upper() in ("JSON_MERGE_PRESERVE", "JSON_MERGE")):
        new_exprs = [e.transform(_rewrite_to_util) if isinstance(e, exp.Expression) else e
                     for e in node.expressions]
        return exp.Anonymous(this="UTIL.JSON_MERGE_PRESERVE", expressions=new_exprs)

    if (isinstance(node, exp.Anonymous)
            and isinstance(node.this, str)
            and node.this.upper() == "ELT"):
        new_exprs = [e.transform(_rewrite_to_util) if isinstance(e, exp.Expression) else e
                     for e in node.expressions]
        return exp.Anonymous(this="UTIL.ELT", expressions=new_exprs)

    _Elt = getattr(exp, "Elt", None)
    if _Elt is not None and isinstance(node, _Elt):
        args = [node.this, *node.expressions]
        new_args = [a.transform(_rewrite_to_util) if isinstance(a, exp.Expression) else a
                    for a in args]
        return exp.Anonymous(this="UTIL.ELT", expressions=new_args)

    if (isinstance(node, exp.Anonymous)
            and isinstance(node.this, str)
            and node.this.upper() == "FIELD"):
        new_exprs = [e.transform(_rewrite_to_util) if isinstance(e, exp.Expression) else e
                     for e in node.expressions]
        return exp.Anonymous(this="UTIL.FIELD", expressions=new_exprs)

    return node


def _wrap_json_objectagg(args):
    if len(args) == 2:
        per_row = exp.Anonymous(this="UTIL.JSON_OBJECT", expressions=list(args))
        listagg = exp.Anonymous(
            this="LISTAGG",
            expressions=[per_row, exp.Literal.string(",")],
        )
        return exp.Anonymous(this="UTIL.JSON_OBJECTAGG", expressions=[listagg])
    return exp.Anonymous(this="UTIL.JSON_OBJECTAGG", expressions=args)


def _strip_sql_quotes(rendered):
    if len(rendered) >= 2 and rendered[0] == "'" and rendered[-1] == "'":
        return rendered[1:-1].replace("''", "'")
    return rendered


_EXASOL_BARE_KEYWORDS = frozenset({
    "CURRENT_SESSION",
    "CURRENT_STATEMENT",
    "CURRENT_SCHEMA",
})


def _alias_unaliased_select(select):
    new_projs = []
    for i, proj in enumerate(select.expressions):
        if isinstance(proj, (exp.Alias, exp.Column, exp.Star)):
            new_projs.append(proj)
        else:
            new_projs.append(exp.alias_(proj, f"_col{i}"))
    select.set("expressions", new_projs)
;

